 report['criticalFastForward']=page.evaluate(r'''async()=>{const q=__qa,check=(v,m)=>{if(!v)throw Error(m)},e=new q.SixBallCandyEngine({sleep:()=>Promise.resolve()});e.presentationRate=3;e.paused=false;let wall=0;e.sleep=async ms=>{wall+=ms};const token=e.version;check(await e.wait(240,token),'accelerated wait aborted');check(wall<=90,'3x fast-forward did not remain active');const fx={steps:[{ms:90,grid:q.sixEmpty(10),moves:[]}],motionMs:90,elapsed:90,grid:q.sixEmpty(10)},f=q.sixFallFrame(fx,.25);check(f.progress===1,'fall did not reach landing before stage end');return {presentationRate:e.presentationRate,acceleratedWallMs:wall,fallCompletes:true}}''')
